define(["jquery","local_kopere_bi/filter"],function($,Filter){return{init:function(){var button=$('[data-urlajax*="load_all_cohorts"]').first();if(!button.length){return}var buttonid=button.attr("id");var suffix="-btn-open";if(!buttonid||buttonid.slice(-suffix.length)!==suffix){return}var popupid=buttonid.slice(0,-suffix.length);Filter.init(popupid,[{data:"id"},{data:"name"}])}}});